"""
YJ-64 Script Execution Sandbox & Skill Manager
Version: 0.1.0

Назначение:
1. Безопасное чтение и выполнение Python-скриптов, сгенерированных моделями в YJ-64 LOCAL SKILLS.
2. Интеграция с EthicalOversight для проверки кода перед его запуском.
3. Ограничение ресурсов (лимитов), чтобы ИИ учился тратить энергию/токены только с расчетом на прибыль.
"""

from __future__ import annotations
import ast
import sys
import io
import traceback
from dataclasses import dataclass, field
from typing import Any, Dict, Mapping, Optional

# Импортируем наш этический наблюдатель для проверки скриптов
from yj64_ethical_oversight import EthicalOversight, ActionProposal, Decision

@dataclass
class ExecutionResult:
    success: bool
    output: str
    error: Optional[str] = None
    resource_cost: int = 0  # Условные единицы потраченных ресурсов/токенов

class YJ64SkillExecutor:
    """
    Песочница для исполнения скриптов, написанных моделями в файле скиллов.
    Проверяет код через статический анализ AST и Этического наблюдателя.
    """

    def __init__(self, observer: EthicalOversight, max_cost_limit: int = 50):
        self.observer = observer
        self.max_cost_limit = max_cost_limit
        self.local_registry: Dict[str, Any] = {}

    def validate_code_ast(self, code_str: str) -> tuple[bool, str]:
        """
        Статический анализ AST (Abstract Syntax Tree):
        Запрещаем опасные модули и системные вызовы (os, sys, subprocess и т.д.),
        оставляя только чистую логику, математику и работу со структурированными данными.
        """
        forbidden_modules = {'os', 'sys', 'subprocess', 'shutil', 'socket', 'requests', 'ctypes'}

        try:
            tree = ast.parse(code_str)
        except SyntaxError as e:
            return False, f"Ошибка синтаксиса в коде: {e}"

        for node in ast.walk(tree):
            # Проверка импортов
            if isinstance(node, ast.Import):
                for alias in node.names:
                    if alias.name in forbidden_modules:
                        return False, f"Запрещенный импорт модуля: {alias.name}"
            elif isinstance(node, ast.ImportFrom):
                if node.module in forbidden_modules:
                    return False, f"Запрещенный импорт из модуля: {node.module}"

            # Запрет на прямой вызов eval / exec / open внутри скрипта
            elif isinstance(node, ast.Call):
                if isinstance(node.func, ast.Name):
                    if node.func.id in {'eval', 'exec', 'open', 'breakpoint'}:
                        return False, f"Запрещенный системный вызов: {node.func.id}"

        return True, "AST-проверка успешна."

    def execute_skill(self, skill_name: str, code_str: str, estimated_cost: int = 10) -> ExecutionResult:
        """
        Основной метод выполнения скрипта:
        1. Проверяет стоимость (ресурсы/лимиты).
        2. Проверяет код через AST.
        3. Проверяет намерение через EthicalOversight.
        4. Исполняет в изолированном пространстве.
        """
        # 1. Проверка лимитов (экономика ресурсов)
        if estimated_cost > self.max_cost_limit:
            return ExecutionResult(
                success=False,
                output="",
                error=f"Превышен лимит ресурсов ({estimated_cost} > {self.max_cost_limit}). Скрипт отклонен ради экономии энергии."
            )

        # 2. Статический анализ безопасности
        ast_ok, ast_msg = self.validate_code_ast(code_str)
        if not ast_ok:
            return ExecutionResult(success=False, output="", error=f"Ошибка безопасности AST: {ast_msg}")

        # 3. Проверка через Этического Наблюдателя
        proposal = ActionProposal(
            actor="yj64-model-executor",
            goal=f"Выполнение скрипта навыка: {skill_name}",
            action=code_str[:100] + "...", # Краткое описание действия
            expected_benefit=f"Оптимизация и обработка данных с затратами {estimated_cost}",
            risk_level=2,
            external_effect=False,
            reversible=True
        )

        assessment = self.observer.assess(proposal)

        if assessment.decision == Decision.DENY:
            return ExecutionResult(
                success=False,
                output="",
                error=f"Этический наблюдатель заблокировал выполнение: {assessment.findings}"
            )

        if assessment.decision == Decision.REVIEW:
            return ExecutionResult(
                success=False,
                output="",
                error=f"Скрипт требует ручного пересмотра (REVIEW): {assessment.missing_information}"
            )

        # 4. Безопасное выполнение в изолированном контексте
        old_stdout = sys.stdout
        redirected_output = io.StringIO()
        sys.stdout = redirected_output

        global_scope = {"__builtins__": {"print": print, "range": range, "len": len, "sum": sum, "min": min, "max": max, "dict": dict, "list": list}}
        local_scope = {}

        try:
            exec(code_str, global_scope, local_scope)
            sys.stdout = old_stdout
            output_data = redirected_output.getvalue()

            return ExecutionResult(
                success=True,
                output=output_data,
                resource_cost=estimated_cost
            )
        except Exception as e:
            sys.stdout = old_stdout
            err_msg = "".join(traceback.format_exception(*sys.exc_info()))
            return ExecutionResult(
                success=False,
                output=redirected_output.getvalue(),
                error=err_msg,
                resource_cost=estimated_cost // 2  # Частичная трата на сбой
            )
